INSERT INTO `nr` VALUES ('apple_pie','[\"2 c. water\", \"1 1/2 c. sugar\", \"2 tsp. cream of tartar\", \"23 Ritz crackers\", \"1 uncooked pie crust\", \"2 tsp. butter\", \"1 tsp. cinnamon\"]','[\"Bring water, sugar and cream of tartar to a boil and boil 1 minute.\", \"Add Ritz crackers, one at a time.\", \"Allow to boil 2 minutes after last cracker is dropped in.\", \"Remove from heat. Pour into unbaked pie shell.\", \"Dot filling with butter and sprinkle cinnamon over filling.\", \"Bake 20 minutes at 425° (pastry strips can be added across the top before baking, if desired).\"]'),('baby_back_ribs','[\"1-2 slabs of baby back ribs\", \"2 Tbsp pickling spice\", \"water to cover\", \"1 bottle Open Pit BBQ sauce\", \"1-2 c. brown sugar\"]','[\"Place ribs in a large pan.\", \"Cover with water and add pickling spice.\", \"Boil for 1 hour.\", \"Remove ribs and place on outdoor grill. Generously brush on BBQ sauce mixture of brown sugar and Open Pit BBQ sauce.\"]'),('baklava','[\"4 lb. ground nuts (walnuts, pecans or almonds)\", \"1 c. sugar\", \"1 1/2 tsp. cinnamon\", \"1/2 tsp. nutmeg\", \"2 lb. margarine, melted\", \"2 lb. filo dough\"]','[\"Grind nuts fine and mix with sugar and spices.\", \"Grease 11 x 16-inch pan (not a cookie sheet) with butter.\", \"Place 4 sheets of filo into pan.\", \"Brush each sheet with butter.\", \"Sprinkle with nuts thinly.\", \"Cover with 3 sheets of filo, brushing each with butter. Add mixture of nuts again as before.\", \"Repeat this until all nuts are used.\", \"End with 3 sheets of filo on top.\", \"Brush with final butter.\", \"Slice the entire thing into diamond shapes to aid in baking.\", \"Preheat oven to 300°.\", \"Place in oven.\", \"Cook for 1 hour, until lightly brown.\", \"Remove from oven.\", \"Let cool.\"]'),('beef_carpaccio','[\"8 -10 ounces beef tenderloin, from the tip end of the roast\", \"4 cups arugula or 4 cups mixed greens\", \"your favorite vinaigrette (amount to taste)\", \"kosher salt\", \"fresh ground black pepper\", \"shaved parmesan cheese\"]','[\"Wrap the tenderloin in plastic wrap and place in the freezer for 2 hours.\", \"After 2 hours, unwrap the tenderloin and thinly slice the beef into approximately into 1/8 to 1/4-inch pieces.\", \"Lay out sheets of plastic wrap and place each slice onto the plastic. Top with another piece of plastic and gently pound the meat with a meat mallet until paper thin.\", \"Repeat until all of the meat is sliced and pounded.\", \"Divide the meat evenly among 4 chilled plates. Serve with greens tossed with vinaigrette, salt, pepper and/or Parmesan.\"]'),('beef_tartare','[\"1 lb. ground sirloin (very lean)\", \"1 egg\", \"1 small onion, chopped very fine\", \"2 Tbsp. olive oil\", \"1 tsp. Worcestershire sauce\", \"salt and pepper to taste\"]','[\"Cut away all visible fat from ground sirloin.\", \"Grind meat twice.\", \"Add eggs, onion and olive oil.\", \"Mix very well.\", \"Add Worcestershire sauce, salt and pepper to taste.\", \"Form into mound.\"]'),('beet_salad','[\"1 can beets, drained well and liquid reserved\", \"1 c. sugar\", \"1 (6 oz.) pkg. raspberry Jell-O\", \"1 Tbsp. unflavored gelatin\", \"1/2 c. wine vinegar\", \"1 tsp. onion, grated\", \"1 tsp. mustard seed\"]','[\"Mash beets.\", \"Combine reserved liquid with enough water to make 3 cups.\", \"Heat and add sugar.\", \"Add Jell-O and gelatin; dissolve.\", \"Let mixture cool.\", \"Pour vinegar over beets.\", \"Fold beets, onion, and mustard seed into jello mixture.\", \"Allow to cool and gel.\"]'),('beignets','[\"1/2 c. warm water\", \"1 pkg. dry yeast\", \"2 tsp. sugar\", \"3/4 c. milk\", \"1/2 tsp. vanilla\", \"1/4 c. unsalted butter, melted\", \"1 egg, lightly beaten\", \"1/3 c. sugar\", \"1 tsp. salt\", \"1/2 tsp. grated nutmeg\", \"3 1/2 c. flour\", \"vegetable oil (for frying)\", \"powdered sugar\"]','[\"In a small bowl, combine water, yeast and 2 teaspoons sugar. Let stand about 10 minutes, until yeast foams.\", \"Meanwhile, combine milk, vanilla, butter, egg, 1/3 cup sugar, salt and nutmeg.\", \"Stir in the yeast mixture.\", \"Add the flour, one cup at a time, mixing well after each addition.\", \"After three cups have been added, knead in the remaining flour, 1 to 2 tablespoons at a time.\", \"Knead until smooth, about 10 minutes.\", \"Place dough in an oiled bowl, turning to coat.\", \"Cover and let rise in a warm place until doubled in bulk, about 1 1/2 hours.\", \"Punch down dough and roll to a 1/2-inch thickness.\", \"Cut the dough into 2-inch diamond shapes.\", \"Place on ungreased baking sheets.\", \"Cover and let rise in a warm place until doubled, about 1 hour.\", \"Pour oil to a depth of 3-inches in a heavy pot or fryer.\", \"Heat to 365° and fry the beignets, 4 or 5 at a time, for 2 to 3 minutes on each side.\", \"Drain on paper towel and place in a warm oven while frying the remaining beignets.\", \"Sprinkle with powdered sugar before serving warm.\", \"Makes about 30.\"]'),('bibimbap','[\"3 tablespoons soy sauce\", \"3 tablespoons white sugar\", \"5 tablespoons sesame oil, divided, or to taste\", \"1 tablespoon garlic, minced\", \"1 teaspoon minced fresh ginger root\", \"1/2 pound beef brisket, thinly sliced, or to taste\", \"1 cup uncooked white rice\", \"1 1/2 cups water\", \"1 cup dried shiitake mushrooms\", \"1 small eggplant, cut into 1/4-inch slices\", \"salt to taste\", \"1 small yellow squash, cut into 1/4-inch slices\", \"2 carrots, chopped\", \"1 cup broccoli florets\", \"1 cup bean sprouts\", \"2 eggs\", \"1 1/2 tablespoons rice vinegar\", \"4 leaves red leaf lettuce, cut widthwise into strips\", \"1 daikon radish, peeled and cut into matchsticks\", \"2 green onions, chopped (optional)\"]','[\"Mix soy sauce, sugar, sesame oil, garlic, and ginger together in a bowl. Add beef brisket and cover with plastic wrap. Marinate in the refrigerator for for 30 minutes.\", \"Rinse rice until water turns clear. Pour into a rice cooker and add 1 1/2 cups water. Seal and select setting according to manufacturer\'s instructions; cook until tender, 20 to 30 minutes. Keep warm.\", \"Place mushrooms in a bowl of warm water. Soak for 20 minutes.\", \"Coat eggplant with salt on all sides and allow to \'sweat,\' about 10 minutes. Rinse with cool water.\", \"Squeeze the water out of the re-hydrated shiitake mushrooms and slice into 1/4-inch strips.\", \"Heat 2 tablespoons sesame oil in a skillet over medium-high heat. Saute mushrooms until lightly browned, about 4 minutes. Transfer to a covered plate to keep warm.\", \"Saute eggplant in the same skillet until slightly softened, about 5 minutes. Transfer to the plate with the mushrooms.\", \"Place squash in the hot skillet; cook and stir until slightly tender, about 5 minutes. Add to the plate with the eggplant and mushrooms; keep vegetables warm.\", \"Saute carrots and broccoli in the skillet until slightly tender, about 6 minutes. Transfer to the plate with rest of the vegetables.\", \"Bring a large pot of water to a boil. Add sprouts and cook uncovered until tender but still crispy, about 2 minutes. Drain in a colander and immediately immerse in ice water for several minutes to stop the cooking process. Drain.\", \"Heat the same skillet over medium-high heat. Add marinated beef slices and saute until nicely browned and lightly pink in the center, about 7 minutes.\", \"Place approximately 1 cup cooked rice in each bowl. Season with remaining sesame oil and vinegar. Pat rice down with a spoon to make a mound. Cover with a bed of lettuce. Add small mounds of cooked mushrooms, eggplant, squash, carrots, and broccoli on the lettuce around the edge of the bowl. Place beef in the center.\", \"Heat the skillet over medium heat. Break eggs into skillet and season with salt. Cook until whites are just set and yolks are slightly runny, about 3 minutes. Place a sunnyside-up egg on top of the beef in each bowl. Top with radish and green onion.\"]'),('bread_pudding','[\"12 slices white bread\", \"1 (8 oz.) pkg. cream cheese, cubed\", \"12 eggs\", \"2 c. milk\", \"1/3 c. maple syrup\", \"1/4 tsp. salt\"]','[\"Remove and discard crusts from bread; cut bread into cubes. Toss lightly with cream cheese cubes.\", \"Place in greased 13 x 9 x 2-inch baking pan.\", \"In a large mixing bowl, beat eggs.\", \"Add milk, syrup and salt.\", \"Mix well.\", \"Pour over bread mixture.\", \"Cover and refrigerate 8 hours or overnight.\"]'),('breakfast_burrito','[\"1 pkg. soft shells (taco or burrito)\", \"1 doz. eggs\", \"1 lb. Polish sausage\", \"1 medium tomato, diced\", \"1 medium potato, diced\", \"1 medium onion, diced\", \"1/2 c. milk\"]','[\"Dice and saute sausage, potato and onion in large skillet. Brown and add tomato pieces.\", \"Crack eggs and stir until well blended as if you\'re scrambling the eggs in large bowl.\", \"Add milk; stir.\", \"When sausage mixture is browned, add egg mixture and scramble.\", \"When the eggs are cooked, put them into the burrito shells (about 3/4 cup into each) and wrap shells around egg mixture.\", \"Put two stuffed burritos in foil and bake for 15 minutes.\"]'),('bruschetta','[\"2 c. chopped ripe tomatoes\", \"2 Tbsp. olive oil\", \"1 clove garlic, minced\", \"1/2 tsp. salt\", \"4 thick slices Italian bread\", \"1 Tbsp. olive oil\"]','[\"Mix first 4 ingredients in a small bowl.\", \"Let stand so tomatoes release their juices.\", \"Brush both sides of bread with olive oil.\", \"Broil 4 to 5 inches from heat source on both sides until lightly browned.\", \"Place bread on serving plates and spoon topping over slices.\", \"Serve immediately.\"]'),('caesar_salad','[\"2 Tbsp. grated Parmesan cheese\", \"2 Tbsp. water\", \"2 Tbsp. red wine vinegar\", \"1 tsp. Worcestershire sauce\", \"1 Tbsp. olive oil\", \"1 clove garlic\", \"1/4 tsp. dry mustard\", \"1 large bunch romaine lettuce, cleaned and torn into pieces\", \"1/3 c. croutons (optional)\"]','[\"Combine all ingredients together except lettuce in food processor and blend until smooth.\", \"Pour over lettuce, tossing well.\", \"Top with croutons, if desired.\", \"Yields 4 servings.\"]'),('cannoli','[\"1 (15 oz.) container Ricotta cheese\", \"2/3 c. confectioners sugar\", \"1/2 tsp. grated orange peel\", \"1/2 tsp. vanilla\", \"2 Tbsp. mini chocolate chips\", \"10 sugar ice cream cones\"]','[\"In a large bowl with electric mixer at low, beat Ricotta, sugar, orange peel and vanilla just until smooth.\", \"Stir in chocolate chips.\", \"Cover.\", \"Refrigerate for 30 minutes.\", \"Spoon mixture into ice cream cones.\", \"Serves 10.\"]'),('caprese_salad','[\"2 pt. cherry tomatoes, halved\", \"4 oz. part-skim Mozzarella cheese, cut into 1/4-inch cubes\", \"1/3 c. slivered green olives\", \"1/3 c. chopped fresh basil\", \"2 Tbsp. balsamic vinegar\", \"1 Tbsp. olive oil\", \"1/2 tsp. salt\"]','[\"In medium bowl, combine all of the ingredients.\", \"Toss and serve.\", \"Will serve 4. High in vitamins A and C. One of the best sources of lycopene.\"]'),('carrot_cake','[\"2 c. flour, sifted\", \"1 tsp. soda\", \"1 tsp. salt\", \"2 c. sugar\", \"1 tsp. cinnamon\", \"1 1/2 c. oil\", \"4 eggs\", \"2 c. grated carrots\", \"1 c. nuts\"]','[\"Place dry ingredients in a large bowl and mix thoroughly.\", \"Add rest of ingredients and mix well.\", \"Bake in well-greased and floured pans.\", \"Bake at 350° for 30 minutes.\", \"Remove from pans and cool.\", \"Makes 2 (9-inch) or 3 (8-inch) layers.\"]'),('ceviche','[\"1 lb. whitefish fillets (raw)\", \"juice of 1 lime\", \"2 medium size tomatoes, peeled\", \"2 green chilies, chopped\", \"1 small onion, thinly sliced\", \"1/4 tsp. oregano\", \"3 sprigs cilantro, chopped\", \"slices of 1 avocado\", \"wedges of 1 tomato\"]','[\"Cut uncooked fish into small pieces.\", \"Add lime juice to cover fish; cover and refrigerate 3 to 4 hours, or until fish become opaque.\", \"Stir occasionally.\"]'),('cheesecake','[\"1/2 c. sugar\", \"8 oz. cream cheese\", \"8 oz. Cool Whip\", \"1 c. sour cream\", \"2 tsp. vanilla\", \"1 frozen graham cracker crust\"]','[\"Mix all ingredients together and pour into graham cracker crust. Add fresh fruit or any canned fruit pie filling on top. Refrigerate 2 hours.\"]'),('cheese_plate','[\"3 ounces sliced drunken goat cheese\", \"3 ounces sliced manchego cheese (may sub any sharp, sturdy white cheese)\", \"20 onion flavored crackers\", \"1/4 cup blackberry jam\", \"2 tablespoons sunflower seeds\", \"2 tablespoons pepitas (shelled pumpkin seeds)\"]','[\"Get out a nice square platter and 2 small bowls (which fit on the platter).\", \"Place goat cheese fanned out in one corner.\", \"Fan the manchego out on the opposite corner.\", \"Place jam/preserves in one bowl and place in an empty corner of the plate.\", \"Then mix the seeds together in the remaining bowl and place in the opposite corner.\", \"Feel free to garnish the plate with fresh berries and mint if you have some.\", \"Place crackers on another plate and serve!\", \"Guests will take 1 cracker, put 1 piece of cheese on it, spread a small amt of jam on the cheese and top with a small sprinkling of the seed. DELISH! (NOTE: You can also serve them on a platter already made up in this manner).\"]'),('chicken_curry','[\"4 (6 oz.) boneless, skinned chicken breasts\", \"3 Tbsp. flour\", \"1 Tbsp. curry powder\", \"4 Tbsp. oil\", \"1 Tbsp. sugar\", \"2 chicken bouillon cubes\", \"1 c. water\", \"16 oz. can apricots\", \"1/2 c. chopped onion\", \"1 c. sliced mushrooms\", \"2 Tbsp. soy sauce\", \"2 Tbsp. lemon juice\"]','[\"Rub chicken breasts with curry powder and put in baking dish. Pour on orange juice sweetened with a little honey.\", \"Bake until done in very slow oven (or adjust for microwave).\", \"Thicken juices with cornstarch.\", \"Serve with brown or white rice.\", \"(Slow oven is 300° and would take about 1 1/2 hours, depending on the number of chicken breasts.)\"]'),('chicken_quesadilla','[\"flour tortillas\", \"chicken breast (boneless) strips\", \"Chihuahua cheese, grated\", \"green onions, chopped (optional)\", \"butter (real butter)\"]','[\"Season chicken and cook.\", \"Lightly butter pan.\", \"Put tortilla in pan.\", \"Place chicken, onion and cheese on 1/2 of tortilla and fold in half.\", \"Cook until fairly toasted on one side and flip over. Cook until toasted and cheese is melted.\"]'),('chicken_wings','[\"1 pkg. chicken wings\", \"1 c. sugar\", \"1 c. soy sauce\", \"1 1/2 tsp. ginger\", \"1/4 tsp. pepper\", \"1/4 tsp. m.s.g.\", \"1/2 c. chopped green onion\"]','[\"Mix all ingredients with chicken wings and marinate in refrigerator overnight.\", \"Bake in uncovered pan in single layers at 325° for 1 1/2 hours.\", \"Stir midway through.\"]'),('chocolate_cake','[\"2 c. flour\", \"2 c. sugar\", \"1 tsp. salt\", \"1 tsp. baking powder\", \"2 tsp. baking soda\", \"3/4 c. cocoa powder\", \"1 c. oil\", \"1 c. hot coffee\", \"2 eggs\", \"1 tsp. vanilla\"]','[\"Mix together and put in 9 x 13-inch cake pan or 9-inch round pans.\", \"Bake at 350° for 35 to 40 minutes.\", \"Very moist chocolate cake.\"]'),('chocolate_mousse','[\"12 oz. Nestle semi-sweet chocolate morsels\", \"6 Tbsp. cold water\", \"4 Tbsp. sugar\", \"6 eggs, separated\", \"1 1/2 pt. heavy cream\", \"2 tsp. vanilla\", \"2 pkg. ladyfingers (unfilled type)\", \"sprinkling of chocolate sprinkles\", \"2 Tbsp. sugar\"]','[\"Make one day in advance!\", \"Line bottom of spring-form pan with wax paper (trace pan bottom onto wax paper; cut and fit into pan bottom).\", \"Melt chocolate morsels and 6 tablespoons water in double boiler.\", \"Add sugar.\", \"Remove from heat.\", \"Add 6 egg yolks.\", \"Beat egg whites until stiff.\", \"Fold into chocolate mixture.\", \"(Do in large bowl.)\", \"Beat 1 pint heavy cream, adding vanilla.\", \"Fold into chocolate mixture.\", \"Line bottom and sides of pan with ladyfingers (there will be a couple of leftover ones) to form picket fence. Chill overnight.\", \"Two hours before serving, beat 1/2 pint heavy cream with 2 tablespoons sugar.\", \"Pour over mousse, then sprinkle with chocolate sprinkles immediately before serving.\"]'),('churros','[\"1 1/2 c. Bisquick\", \"1 c. water\", \"1 egg\", \"1/2 tsp. cinnamon\", \"1 Tbsp. sugar plus a little extra\", \"vegetable oil\"]','[\"In small saucepan, combine Bisquick and cinnamon.\", \"In a 1-quart saucepan, heat water and 1 tablespoon sugar to boiling. Add boiling mixture to Bisquick mixture.\", \"Reduce heat and stir vigorously until dough forms a ball.\", \"Remove from heat; beat in egg until smooth.\", \"Transfer dough into a pastry bag fitted with a star tip.\", \"Pipe 5-inch strips into a hot skillet with 1-inch of oil.\", \"Cook until golden brown on all sides, turning to coat evenly.\", \"While still hot, roll in extra sugar.\", \"Serve warm.\"]'),('clam_chowder','[\"6 to 8 large potatoes, diced\", \"3 medium onions, diced\", \"2 small green peppers, chopped\", \"5 stalks celery, chopped\", \"1 1/2 tsp. thyme\", \"1 Tbsp. salt\", \"1 tsp. pepper\", \"juice of 1 lemon\", \"4 c. water\", \"6 to 7 cans minced clams (juice and all)\", \"1/2 c. flour\", \"1 qt. half and half\", \"1/2 lb. melted butter\", \"dash or 2 Tabasco\", \"sherry\"]','[\"Simmer first 9 ingredients until vegetables are tender, 30 to 45 minutes.\", \"Add minced clams, juice and all.\", \"Cook another 5 minutes.\", \"In blender mix flour, 1/2 quart half and half and melted butter.\", \"Add to chowder.\", \"Then add rest of half and half.\", \"Add 1/8 to 1/4 pound more butter and a dash or 2 of Tabasco.\", \"Serve with 1 tablespoon sherry (I add more).\"]'),('club_sandwich','[\"3 slices buttered toast\", \"lettuce\", \"cold sliced chicken\", \"mayonnaise\", \"tomato slice\", \"2 to 3 strips crisp cooked bacon\"]','[\"For each sandwich:\", \"Top first slice of toast with lettuce and cold chicken slice.\", \"Add mayonnaise, if desired.\", \"Top with second toast slice.\", \"Add tomato slice and bacon strips.\", \"Top with third slice of toast.\", \"Peg with 4 toothpicks.\", \"Cut in quarters diagonally.\", \"Serve with sandwiches, point up.\"]'),('crab_cakes','[\"1 Tbsp. Worcestershire sauce\", \"2 or 3 shakes Old Bay\", \"1 tsp. dry mustard\", \"2 Tbsp. mayonnaise\", \"1 egg\"]','[\"Mix together and carefully add 1 pound lump crab meat.\", \"Mix ahead of time and refrigerate so they will hold together better.\"]'),('creme_brulee','[\"3 c. heavy cream\", \"1/3 c. whole milk\", \"3/4 c. plus 2 Tbsp. sugar, divided\", \"1 whole vanilla bean, or 2 tsp. vanilla extract\", \"6 large egg yolks\", \"1 large egg\", \"1 tsp. vanilla extract\", \"4-6 Tbsp. sugar, for topping\"]','[\"In a large, heavy saucepan, combine the cream, milk and 1/2 cup of the sugar. Place the pan over high heat and bring to a boil, watching carefully to prevent a boil-over, then remove from the heat. Add 2 teaspoons vanilla extract, or, if using a vanilla bean, cut the vanilla bean on a cutting board in half lengthwise and scrape the seeds out with the tip of a sharp knife. Add the seeds and the pod to the pan. Let the cream mixture stand for 30 minutes.\"]'),('croque_madame','[\"1 egg\", \"2 pieces bread\", \"1 piece cheese\", \"1 slice ham\"]','[\"Smear bread with butter.\", \"Put 1 piece into a hot skillet with the butter facing the bottom.\", \"Put cheese and ham and bread (butter side up).\", \"Brown both sides.\", \"Fry an egg and put it on top of the grilled open-faced ham and cheese sandwich.\"]'),('cup_cakes','[\"2 C. flour\", \"2 C. sugar\", \"2 eggs\", \"2 tsp. soda\", \"20 oz. can pineapple\"]','[\"Mix together by hand. Bake in 350 degrees oven 35 minutes.\"]'),('deviled_eggs','[\"6 eggs\", \"1 Tbsp. mustard\", \"1 Tbsp. sugar\", \"1/4 c. Miracle Whip\", \"1/8 tsp. salt\", \"dash of pepper\"]','[\"Cook eggs 10 minutes, then drain off water.\", \"Cover with cold water to cool eggs some, then peel hard-boiled eggs.\", \"Cut into halves lengthwise\", \"and\", \"scoop\", \"yolks out into bowl.\", \"Mash with fork until\", \"real\", \"fine, add mustard, Miracle Whip, sugar, salt and pepper.\", \"Spoon\", \"into\", \"egg\", \"halves\", \"and\", \"sprinkle with paprika.\"]'),('donuts','[\"1 can biscuits (10)\", \"powdered sugar\"]','[\"Cut\", \"small\", \"hole in middle of biscuits.\", \"I use medicine bottle.\", \"Deep fry biscuits and the holes until brown.\", \"Roll in powdered sugar.\"]'),('dumplings','[\"1 c. flour\", \"1 tsp. baking powder\", \"pinch of salt\", \"1 large egg\", \"1 tsp. melted butter\", \"1/3 c. milk\"]','[\"Sift dry ingredients into a bowl.\", \"Beat in the egg until it is well mixed.\", \"Then add the milk and work it with a heavy spoon until smooth.\", \"Drop by tablespoon into boiling broth or salted water.\", \"Let boil with lid closed for 10 minutes.\"]'),('edamame','[\"1 (12 ounce) package frozen edamame (soybeans) in their pods\", \"2 tablespoons extra-virgin olive oil\", \"2 cloves garlic, minced\", \"1 teaspoon sea salt\", \"1/2 teaspoon ground black pepper\"]','[\"Preheat oven to 375 degrees F (190 degrees C).\", \"Toss edamame, olive oil, garlic, sea salt, and black pepper together in a large bowl until well-coated. Spread in a single layer on a baking sheet.\", \"Roast in the preheated oven, stirring halfway through, until edamame shells start to brown, about 20 minutes. Serve whole, popping beans out of the shell to eat.\"]'),('eggs_benedict','[\"8 slices bread, buttered on both sides\", \"1 lb. bacon, fried crisp\", \"1 (8 oz.) pkg. shredded Cheddar cheese\", \"1 c. milk\", \"1 doz. eggs\", \"salt and pepper to taste\", \"1/2 c. chopped onion\", \"1/2 c. chopped green pepper\", \"1 large can mushrooms\"]','[\"Line 9 x 13-inch pan with bread.\", \"Cover with bacon and shredded cheese.\", \"Beat milk, eggs, salt and pepper together.\", \"Add onion and green pepper and fold in mushrooms.\", \"Pour over bread, bacon and cheese.\", \"Cover and refrigerate overnight.\"]'),('escargots','[\"24 snails\", \"2 cloves crushed garlic\", \"1 tsp. fresh parsley\", \"1 tsp. chopped green onion\", \"1/2 tsp. salt\", \"1/8 tsp. pepper\", \"4 Tbsp. white wine\", \"2/3 c. butter\"]','[\"Heat oven to 400°. Mix wine, parsley, butter, garlic, salt, pepper and onion in saucepan.\", \"Heat.\", \"Rinse and strain snails.\"]'),('falafel','[\"1 1/2 c. dried chickpeas (garbanzo beans, about 12 oz.)\", \"2 c. chopped fresh cilantro\", \"1 tsp. cumin\", \"1 tsp. allspice\", \"1/4 tsp. salt\", \"1/4 tsp. black pepper\", \"1/8 tsp. ground red pepper\", \"5 garlic cloves, peeled\", \"1 onion, quartered\", \"1 leek, trimmed and cut into 3 pieces\", \"6 Tbsp. olive oil, divided\", \"Yogurt-Tahini Dip\", \"8 (6-inch) pitas, cut in half\"]','[\"Sort and wash chickpeas and place in large bowl. Cover with water to 2 inches above beans. Cover and let stand for 8 hours. Drain beans. Combine chickpeas, cilantro and next 8 ingredients in a food processor until mixture resembles coarse meal. Divide chickpea mixture into 16 equal portions, shaping each into 1/2 inch thick patties. Heat 2 Tbsp. oil in a large non-stick skillet. Add 5 patties and cook 3 minutes on each side or until golden brown. Repeat procedure twice with remaining oil and patties. Spread 1 Tbsp. Yogurt-Tahini Dip in each pita half. Fill with 1 patty. Serves 8 (2 pita halves each).\"]'),('filet_mignon','[\"1/4 c. dry red wine\", \"2 Tbsp. soy sauce\", \"1/4 tsp. dried tarragon\", \"2 beef tenderloin steaks\", \"vegetable cooking spray\"]','[\"Combine first three ingredients in large Ziploc bag.\", \"Add steaks.\", \"Refrigerate 3 hours, turning occasionally.\", \"Remove steaks from marinade.\", \"Place on coated rack in shallow, roasting pan. Broil 6 inches from heat for 5 minutes each side.\"]'),('fish_and_chips','[\"3 c. pancake mix\", \"3 to 4 c. club soda\", \"4 oz. envelope Ranch dressing mix\", \"2 to 3 lb. fish\"]','[\"Mix first three ingredients until the consistency of buttermilk.\", \"Then dip fish in flour and let dry a few minutes. Then dip in batter.\"]'),('foie_gras','[\"1/2 lb. chicken giblets or chicken liver\", \"1 1/4 tsp. salt\", \"1/2 c. butter\", \"2 tsp. Worcestershire sauce\", \"1 tsp. mustard\", \"1/2 tsp. nutmeg\", \"1/4 tsp. cloves\", \"1/8 tsp. cayenne pepper\", \"2 Tbsp. onion juice\"]','[\"Simmer giblets in water to cover until tender, about 20 minutes for liver; 1 to 3 hours for gizzard.\", \"Add the salt when almost done.\", \"Cool in the stock.\", \"Grind the giblets or liver to a smooth paste; add butter, seasonings and enough of the stock to make a paste.\", \"Add more seasonings, if desired.\", \"Place in a greased glass bowl and store in the refrigerator.\", \"Tomato catsup may be used for additional seasoning.\", \"Makes 1 cup.\"]'),('french_fries','[\"10 oz. potatoes\", \"1 tsp. oil\", \"1/4 tsp. paprika\", \"1/8 tsp. salt\"]','[\"Cut potatoes into 1/2 inch wide sticks.\", \"Place in old water (ice) about 30 minutes.\", \"Pat dry.\", \"Place potatoes in plastic bag with other ingredients.\", \"Shake to coat.\", \"Arrange on large cookie sheet in a single layer.\", \"Bake at 425° for 30 minutes, stirring once or twice until golden brown.\"]'),('french_onion_soup','[\"1/4 lb. butter\", \"2 1/2 lb. onions, sliced\", \"1 qt. beef stock (3 cans Campbell\'s beef stock)\", \"1 qt. chicken stock (3 cans Campbell\'s chicken stock)\", \"2 Tbsp. Worcestershire sauce\", \"1 bay leaf\", \"1 1/2 tsp. garlic salt\", \"1 tsp. black pepper (you may wish to use less)\", \"salt to taste (you may not want any)\"]','[\"Heat butter in heavy kettle.\", \"Add sliced onions; brown well, stirring constantly.\", \"Add beef and chicken stock, the Worcestershire sauce, bay leaf, garlic salt and pepper.\", \"Allow to simmer for 40 minutes.\", \"Remove the bay leaf; add salt.\", \"Prepare with a slice of toasted French bread (1/2-inch thick).\", \"Add a thick slice of Swiss cheese (1/4-inch thick), overlapping the bowl.\", \"Put under the broiler until cheese is melted and bubbly.\"]'),('french_toast','[\"4 eggs\", \"1 c. milk\", \"1 Tbsp. sugar\", \"1/2 tsp. salt\", \"8 slices day-old bread\", \"syrup, jelly or 10xxx sugar\"]','[\"Beat eggs, milk, sugar and salt together in shallow dish. Heat shortening in skillet or on griddle.\", \"Dip bread slices, one at a time, into egg mixture.\", \"Turn and coat evenly.\", \"Fry until lightly brown on both sides.\", \"Serve with syrup, jelly or 10xxx sugar.\"]'),('fried_calamari','[\"1 lb. calamari, cleaned and cut into 1-inch circles\", \"1 c. flour\", \"salt and pepper to taste\", \"2 c. vegetable oil or as needed\"]','[\"Wash and dry calamari as best as possible to avoid splattering. Heat oil until it sizzles when you put in a piece of calamari (test it first).\", \"Dredge calamari lightly in flour and deep fry until golden brown.\", \"Serve hot with lemon juice, tartar sauce, cocktail sauce or hot sauce.\"]'),('fried_rice','[\"1 c. white rice\", \"1/2 c. frozen peas and carrots\", \"2 to 3 Tbsp. onions, diced\", \"1 egg, slightly beaten\", \"2 Tbsp. real bacon bits\", \"1 Tbsp. butter or margarine\", \"light soy sauce to taste\"]','[\"1 c. white rice\", \"1/2 c. frozen peas and carrots\", \"2 to 3 Tbsp. onions, diced\", \"1 egg, slightly beaten\", \"2 Tbsp. real bacon bits\", \"1 Tbsp. butter or margarine\", \"light soy sauce to taste\"]'),('frozen_yogurt','[\"8 oz. fresh strawberries\", \"8 oz. nonfat yogurt\", \"1/2 tsp. Equal sweetener\"]','[\"Put strawberries in blender.\", \"Mix until pureed.\", \"Mix with yogurt and sweetener to taste.\", \"Freeze.\"]'),('garlic_bread','[\"2 Tbsp. butter flavored sprinkles\", \"2 Tbsp. hot tap water\", \"1 Tbsp. grated Parmesan cheese\", \"1 tsp. dried oregano\", \"1 clove garlic, minced\", \"1 loaf French bread, cut in 8 slices\"]','[\"In a cup, stir sprinkles into the water until dissolved.\", \"Stir in Parmesan, oregano and garlic.\", \"With a pastry brush, lightly coat both sides of each bread slice with mixture.\", \"Form bread back into a loaf and place on sheet of aluminum foil. Wrap well. Bake at 350° for 15 minutes.\"]'),('gnocchi','[\"1 lb. Ricotta cheese\", \"2 c. flour\", \"1 egg\"]','[\"Beat egg before you mix in rest of ingredients.\", \"Flour hands and separate dough into 4 sections.\", \"Roll each section into snakes on a floured surface.\", \"Cut 1-inch pieces out of the snakes and, with thumb, press flat.\", \"Fast freeze (about 10 minutes) on a cookie sheet.\", \"When hard, cook in boiling water (salted) for 5 minutes after they rise to the top of the pot.\", \"Serve with spaghetti sauce.\"]'),('greek_salad','[\"1 small head lettuce\", \"1 small cucumber, sliced\", \"1 or 2 tomatoes, cut as desired\", \"1 green pepper, cut into strips\", \"1 small onion, sliced or 4 scallions, chopped\", \"2 stalks celery, chopped\", \"6 radishes, sliced\", \"1/4 c. parsley, finely cut with scissors\", \"1/2 c. crumbled Feta cheese\", \"Calamata or Greek black olives\", \"anchovies (optional)\"]','[\"Break lettuce into small pieces.\", \"Place in large bowl with remaining vegetables.\", \"Pour enough dressing to lightly coat each piece.\", \"Garnish with Feta cheese, olives and anchovies.\"]'),('grilled_cheese_sandwich','[\"2 Tbsp. unsalted butter\", \"4 large mushrooms, sliced\", \"2 medium green onions, minced\", \"1/4 tsp. salt\", \"1/8 tsp. freshly ground pepper\", \"4 oz. cold Brie, cut into 1/8-inch thick slices\", \"8 slices firm textured white bread, crusts removed\", \"4 sprigs fresh tarragon\"]','[\"In a heavy medium skillet, melt the butter over high heat. When the butter begins to brown, add the mushrooms and toss to coat.\", \"Saute, stirring occasionally, until the mushrooms have browned around the edges, 2 to 3 minutes.\", \"Add the green onions and cook for 1 minute longer. Transfer the mushrooms to a plate and season with salt and pepper.\", \"Divide the cheese among 4 slices of bread.\", \"Top each with the mushrooms, leaving about 1/4-inch from the edge of the bread. Add a tarragon sprig and cover with the remaining 4 slices of bread.\", \"Preheat a cast-iron ridged griddle or skillet for 10 minutes over moderate heat. Grill the sandwiches for 4 minutes per side or until the bread is lightly browned and the cheese has melted.\", \"Serve halved as a first course or quartered as an hors d\'oeuvre.\"]'),('grilled_salmon','[\"2 Cloves Garlic (Crushed)\", \"1/3 c. California Orange Juice\", \"1/3 c. Soy Sauce\", \"3 Tbsp. Ketchup\", \"1 Tbsp. Honey\", \"1/2 tsp. Ginger\", \"4 Kodiak Salmon Steaks\"]','[\"1. Mix garlic, OJ, ketchup, honey, and ginger in a shallow dish. Place Salmon steak in the shallow dish and let\", \"soak for at least 15 minutes, but preferably for 1 hour.\", \"2. Turn steaks several times to expose both sides to\", \"marinade.\", \"3. Out Salmon and marinade in a tin foil dish and place on\", \"grill, cover. Cook with medium heat until Salmon is\", \"flaky.\"]'),('guacamole','[\"2 medium tomatoes\", \"1 ripe medium avocado\", \"1 c. low-fat cottage cheese\", \"1 Tbsp. lemon juice\", \"1 tsp. bottled minced garlic or dash of garlic powder\", \"1/8 tsp. salt\", \"few dashes of hot pepper sauce\"]','[\"Cut stem ends off tomatoes and hollow out, leaving 1/4 to 1/2-inch thick shells.\", \"Discard seeds.\", \"Chop tomato pulp and tops. Set aside.\", \"Halve, seed, peel and cut the avocado into chunks. Combine the chunks, cottage cheese, lemon juice, garlic, salt and pepper sauce in blender or food processor until mixture is smooth. Stir in chopped tomato.\", \"Makes 16 (2 tablespoon) servings of dip.\"]'),('gyoza','[\"1 lb. ground beef\", \"1 egg\", \"1/2 to 3/4 c. cabbage, finely chopped\", \"1/2 c. green onion, finely chopped\", \"salt and pepper to taste\", \"1 pkg. wonton wraps\", \"water (one bowl)\", \"oil\"]','[\"Mix first 6 ingredients well.\", \"Take small amounts of meat mixture (about 1 tablespoon) and place in center of wonton wrap. With wet fingers, wet all sides of wonton wrap and fold over into a triangle, pressing all sides down firmly, flattening the meat mixture lightly.\"]'),('hamburger','[\"1 lb. hamburger\", \"1 can golden mushroom soup\", \"flour\", \"2 to 3 tsp. oil\"]','[\"Make hamburger into patties.\", \"Coat with flour and brown lightly in oil.\", \"Add mushroom soup and simmer for about 15 minutes.\"]'),('hot_and_sour_soup','[\"4 dried black mushrooms\", \"1/2 c. dried Chinese fungus\", \"1 c. lean pork\", \"1 c. bamboo shoots\", \"2 Tbsp. oil\", \"12 dried red chili peppers\", \"8 c. chicken broth\", \"2 Tbsp. light soy sauce\", \"1 tsp. pepper\", \"1/2 c. vinegar\", \"3 Tbsp. cornstarch, dissolved in 1/2 c. cold water\", \"1 pkg. fresh tofu or bean curd, cut into thin strips\", \"6 eggs, beaten\", \"1 Tbsp. sesame oil\", \"hot oil (if desired)\", \"2 scallions, chopped\"]','[\"Rehydrate mushrooms and fungus as directed on the package labels.\", \"Separately cut mushrooms, fungus, pork and bamboo shoots to fine julienne.\", \"Stir-fry pork with salt in heated oil.\", \"Bring chicken broth to boil in pot.\", \"Add dried peppers, mushrooms, fungus, pork and bamboo shoots.\", \"Stir frequently.\", \"Add soy sauce, pepper and vinegar.\", \"Thicken with dissolved cornstarch, stirring constantly, over moderate heat.\", \"Add bean curd.\", \"Bring to boil. Turn off heat.\", \"Add beaten eggs and stir.\", \"Add sesame seed oil. Garnish with scallions.\", \"Use additional vinegar for sourness and hot oil for hotness if desired.\"]'),('hot_dog','[\"2 lb. wieners\", \"3/4 c. vinegar\", \"1 1/2 c. catsup\", \"1/2 c. brown sugar\", \"1 1/2 tsp. minced onion\"]','[\"Wieners can be chunked up or left whole.\", \"Mix all ingredients, except wieners.\", \"Bring to a boil.\", \"Add wieners and simmer.\"]'),('huevos_rancheros','[\"2 Tbsp. vegetable oil\", \"4 eggs\", \"1 Tbsp. chopped onion\", \"1 Tbsp. chopped green pepper\", \"1 medium tomato, chopped\", \"1 jalapeno pepper, chopped\", \"salt and pepper to taste\"]','[\"In skillet with oil over slow heat, add all ingredients, except eggs, within 1 minute.\", \"Add eggs, scramble and enjoy with refried beans and tortillas if you were brave enough to include the jalapeno.\", \"Sit down by yourself and enjoy, as no one else will want to make a trip to the creek with you.\"]'),('hummus','[\"2 cans garbanzo beans, drained, rinsed and whirled in food processor until chunky to smooth\", \"2 green onions\", \"1 c. parsley, chopped\", \"2 cloves\", \"crushed garlic\", \"salt\", \"pepper\", \"1/2 to 1 c. sesame paste\"]','[\"When all finely chopped and mixed, add sesame paste (will stiffen mix).\", \"Stir, cover and chill.\", \"Serve with vegetables and pita bread.\"]'),('ice_cream','[\"3 bananas\", \"juice from 3 lemons and 3 oranges\", \"3 c. sugar\", \"3 c. milk\", \"1 tsp. vanilla\"]','[\"Mash bananas, then add the lemon and orange juice.\", \"Add sugar, milk and vanilla.\", \"Pour in a pan and freeze in refrigerator.\"]'),('lasagna','[\"1 lb. ground beef\", \"1 medium onion, chopped\", \"1 large jar meatless spaghetti sauce\", \"1 pkg. lasagna noodles\", \"1 pkg. Swiss cheese\", \"1 pkg. Cheddar cheese\", \"1 pkg. Mozzarella cheese\", \"salt and pepper to taste\", \"oregano to taste\", \"red pepper to taste\", \"powdered garlic to taste\"]','[\"Brown beef and onions; drain and add salt, pepper, oregano, red pepper and powdered garlic.\", \"Add spaghetti sauce and simmer. Cook noodles about 20 minutes.\", \"Drain noodles and add butter so they don\'t stick.\"]'),('lobster_bisque','[\"1 (46 oz.) College Inn broth plus 1 c. water\", \"1 pkg. Knorr Newberg sauce mix\", \"8 oz. lobster meat (fresh or frozen)\", \"3 sticks butter\", \"1/3 c. brandy\", \"2/3 c. dry sherry\", \"4 pt. light cream\", \"1 1/4 c. all-purpose flour\", \"garlic powder to taste\"]','[\"Heat chicken broth, diluted with 1 cup water, in saucepan. Keep hot.\", \"Lightly saute lobster meat in 1/2 stick of butter (1/4 cup).\", \"Season with garlic powder to taste.\", \"Add brandy.\", \"Remove from heat and allow to cool.\", \"Process in food processor to chop. In a large pot, melt remaining butter (1 1/4 cups or 2 1/2 sticks); add 1 1/2 cups flour and Newberg sauce mix to make a roux.\", \"Cook roux over very low heat 3 to 5 minutes.\", \"Slowly add hot chicken broth to roux, mixing thoroughly with whisk after each addition. Mixture will be very thick.\"]'),('lobster_roll_sandwich','[\"1/2 cup mayonnaise\", \"2 teaspoons Dijon mustard\", \"1/3 cup celery, diced\", \"1 tablespoon fresh lemon juice\", \"1/4 teaspoon Old Bay Seasoning\", \"3 cups lobster meat, cooked and cut into bite sized chunks\", \"6 lettuce leaves\", \"6 hot dog rolls\"]','[\"Combine first five ingredients in a mixing bowl; mix well.\", \"Line the roll with lettuce.\", \"Stuff the lobster salad into the hot dog rolls.\"]'),('macaroni_and_cheese','[\"1 (8 oz.) pkg. elbow macaroni\", \"1/4 c. butter or margarine\", \"1/4 c. all-purpose flour\", \"1 tsp. salt\", \"1/8 tsp. pepper\", \"2 c. milk\", \"2 c. (8 oz.) Cheddar cheese, grated\", \"1 large tomato, thickly sliced\"]','[\"Preheat oven to 375°.\", \"Cook macaroni as package label directs; drain.\", \"Meanwhile, melt butter in medium saucepan.\", \"Remove from heat.\", \"Stir in flour, salt and pepper until smooth.\", \"Gradually stir in milk.\", \"Bring to boiling, stirring.\", \"Reduce heat and simmer mixture 1 minute.\", \"Remove from heat.\", \"Stir in 1 1/2 cups cheese and the macaroni.\", \"Pour into a 1 1/2-quart shallow casserole. Arrange tomato slices over top.\", \"Sprinkle remaining cheese over top.\", \"Bake 15 minutes or until cheese is golden brown.\", \"Makes 4 to 6 servings.\"]'),('macarons','[\"4 extra large egg whites\", \"1 2/3 cups confectioners\' sugar\", \"1 1/3 cups almond flour\", \"1/8 teaspoon salt\", \"1/4 cup superfine (castor) sugar\"]','[\"Place egg whites into a metal mixing bowl and refrigerate overnight. The next day, bring egg whites to room temperature.\", \"Preheat oven to 280 degrees F (138 degrees C). Line baking sheets with parchment paper.\", \"Whisk confectioners\' sugar and almond flour in a bowl. Beat the egg whites with salt in metal bowl with an electric mixer on medium speed until foamy, about 1 minute; increase speed to high and gradually beat in superfine sugar, about 1 tablespoon at a time, until the egg whites are glossy and hold stiff peaks, 3 to 5 more minutes.\", \"Gently fold almond flour mixture into whipped egg whites until thoroughly incorporated; spoon meringue into a pastry big fitted with a 3/8-inch tip.\", \"Pipe 1-inch disks of meringue onto the prepared baking sheets, leaving 2 inches of space between cookies. The batter will spread. Lift the baking sheets a few inches above the work surface and hit them lightly on the work surface several times to remove any air bubbles from the cookies. Let the cookies stand at room temperature until the shiny surfaces become dull and a thin skin forms, about 15 minutes.\", \"Place the baking sheets in the preheated oven and bake with the oven door open slightly until the macarons\' surfaces are completely dry, about 15 minutes. Let cookies cool completely on a baking sheet before peeling parchment paper from the cookies.\", \"Spread half the cookies with any desired filling, top with remaining cookies to make sandwiches, and refrigerate at least 2 hours to overnight to let the cookies soften.\"]'),('miso_soup','[\"4 c. dashi (4 c. water and 1 Tbsp. hondashi, Japanese seasoning)\", \"3 oz. lean pork\", \"3 to 4 Tbsp. miso, or to taste\", \"1 long green onion and top, cut into 1/2-inch lengths or 2-inch onions cut crosswise into thin slices\", \"2 tsp. ginger juice*\"]','[\"*Peel and grate fresh ginger root, then squeeze.\"]'),('mussels','[\"3 to 5 lb. washed mussels\", \"2 cloves fresh garlic\", \"2 c. wine\"]','[\"Steam for 5 minutes.\", \"Dip in melted butter.\"]'),('nachos','[\"1 pkg. cream cheese\", \"1 can chili\", \"1 c. Monterey Jack cheese\", \"1/2 c. Cheddar cheese\"]','[\"Spread package of cream cheese on bottom of pie plate.\", \"Spread can of chili on top of cream cheese.\", \"Sprinkle the 2 cheeses on top.\", \"Bake at 350° until cheese melts.\", \"Serve with tortilla chips.\"]'),('omelette','[\"eggs\", \"bacon or ham\", \"cheese\", \"green peppers or other vegetables\", \"vegetable oil\"]','[\"Cook bacon or ham.\", \"Beat eggs; pour in hot skillet with oil. Add cheese slices.\", \"Crumble bacon.\", \"Dice peppers and onions and add.\", \"Cook until eggs bubble and hold together.\", \"Then fold one side over other.\", \"Cook until done.\", \"Do not overcook or burn.\"]'),('onion_rings','[\"1 c. flour\", \"1/4 tsp. salt\", \"1/2 c. milk\", \"2 Tbsp. salad oil\", \"1 egg white (unbeaten)\", \"6 Tbsp. water\", \"2 to 3 large onions\"]','[\"Mix together in large bowl.\", \"Cut onions into slices; separate into rings.\", \"Deep-fry in hot oil.\"]'),('oysters','[\"12 oz. pkg. frozen spinach souffle\", \"1 pt. oysters, drained\", \"dash of Tabasco\", \"3 Tbsp. Parmesan cheese\", \"2 Tbsp. melted butter\", \"1/2 tsp. minced onion\", \"1/4 c. seasoned crumbs\"]','[\"Mix together spinach, oysters, onions and Tabasco and put into casserole dish.\", \"Top with bread crumbs, butter and Parmesan.\", \"Bake at 350° for 50 to 60 minutes.\"]'),('pad_thai','[\"1/2 lb. linguine (fresh is best)\", \"3 Tbsp. soy sauce\", \"2 tsp. sugar\", \"3 Tbsp. vegetable oil or butter\", \"1/2 lb. boneless chicken breast, cut into small pieces\", \"1/2 lb. bean sprouts, drained\", \"1/2 lb. cooked shrimp\", \"curry powder and/or cayenne pepper\", \"3/4 c. tomato juice\", \"1 Tbsp. vinegar\", \"3/4 tsp. cornstarch\", \"garlic to taste\", \"1/2 c. chopped green onions and tops\"]','[\"Cook linguine according to package directions; drain.\", \"Combine tomato juice, soy sauce, vinegar, sugar and cornstarch; set aside. Heat 1 tablespoon of oil or butter in hot wok or large skillet. Add chicken and stir-fry 1 minute; remove.\", \"(I cook my chicken until it is completely done which takes quite a bit longer than 1 minute.)\", \"Add garlic, bean sprouts and green onions and stir-fry for 1 minute.\", \"Stir in linguine and cook 2 more minutes or until heated through.\", \"Return chicken with shrimp, curry, pepper and tomato mixture.\", \"Cook, stirring until sauce boils and thickens. Makes 4 servings.\"]'),('paella','[\"1 lb. chicken, cut in small pieces\", \"1 lb. rabbit, cut in small pieces\", \"1/2 lb. pork, chopped, boned and cut in small pieces\", \"1 lb. mussels\", \"1 lb. shrimp, leave in shell\", \"1 clove garlic\", \"1 lb. clams\", \"3 tomatoes, peeled and chopped\", \"1 small onion, chopped\", \"1 Tbsp. parsley\", \"1/2 lb. scallops\", \"1 can peas or frozen\", \"pinch of saffron or 2 tsp. turmeric\", \"olive oil for frying\", \"1 chopped green pepper\"]','[\"In a paella pan or large skillet, fry chicken and rabbit. Remove.\", \"In same pan, cook pork.\", \"Remove.\", \"In pan, saute onion, green pepper and garlic.\", \"Add to the vegetables and chopped tomatoes.\", \"Add parsley.\", \"Re-add poultry and pork.\", \"Mix well.\", \"Add all seafood that has been washed.\", \"Fill pan with water and bring to a boil.\", \"Add 2 cups rice and saffron/turmeric and bring to second boil.\", \"Add peas.\", \"Simmer for 20 minutes or until rice is cooked.\", \"Garnish with red peppers, sliced lemons or sliced oranges.\"]'),('pancakes','[\"1 c. flour\", \"1 tsp. soda\", \"1 tsp. salt\", \"1 Tbsp. sugar\", \"1 egg\", \"3 Tbsp. margarine, melted\", \"1 c. buttermilk\"]','[\"Mix dry ingredients.\", \"Add egg, margarine and buttermilk. Stir by hand until well blended.\", \"Pour onto non-stick pan or griddle with a little oil added.\", \"Cook until bubbly and turn over.\"]'),('panna_cotta','[\"1/3 cup skim milk\", \"1 (.25 ounce) envelope unflavored gelatin\", \"2 1/2 cups heavy cream\", \"1/2 cup white sugar\", \"1 1/2 teaspoons vanilla extract\"]','[\"Pour milk into a small bowl, and stir in the gelatin powder. Set aside.\", \"In a saucepan, stir together the heavy cream and sugar, and set over medium heat. Bring to a full boil, watching carefully, as the cream will quickly rise to the top of the pan. Pour the gelatin and milk into the cream, stirring until completely dissolved. Cook for one minute, stirring constantly. Remove from heat, stir in the vanilla and pour into six individual ramekin dishes.\", \"Cool the ramekins uncovered at room temperature. When cool, cover with plastic wrap, and refrigerate for at least 4 hours, but preferably overnight before serving.\"]'),('peking_duck','[\"1 (4 pound) whole duck, dressed\", \"1/2 teaspoon ground cinnamon\", \"1/2 teaspoon ground ginger\", \"1/4 teaspoon ground nutmeg\", \"1/4 teaspoon ground white pepper\", \"1/8 teaspoon ground cloves\", \"3 tablespoons soy sauce\", \"1 tablespoon honey\", \"1 orange, sliced in rounds\", \"1 tablespoon chopped fresh parsley, for garnish\", \"5 green onions\", \"1/2 cup plum jam\", \"1 1/2 teaspoons sugar\", \"1 1/2 teaspoons distilled white vinegar\", \"1/4 cup finely chopped chutney\"]','[\"Rinse the duck inside and out, and pat dry. Cut off tail and discard. In a small bowl, mix together the cinnamon, ginger, nutmeg, white pepper and cloves. Sprinkle one teaspoon of the mixture into the cavity of the duck. Stir one tablespoon of the soy sauce into the remaining spice mixture and rub evenly over the entire outside of the bird. Cut one of the green onions in half and tuck inside the cavity. Cover and refrigerate the bird for at least 2 hours, or overnight.\", \"Place duck breast side up on a rack in a big enough wok or pot and steam for an hour adding a little more water, if necessary, as it evaporates. Lift duck with two large spoons, and drain juices and green onion.\", \"Preheat the oven to 375 degrees F (190 degrees C). Place duck breast side up in a roasting pan and prick skin all over using a fork.\", \"Roast for 30 minutes in the preheated oven. While the duck is roasting, mix together the remaining 2 tablespoons of soy sauce and honey. After 30 minutes, brush the honey mixture onto the duck and return it to the oven. Turn the heat up to 500 degrees F (260 degrees C). Roast for 5 minutes, or until the skin is richly browned. Do not allow the skin to char.\", \"Prepare the duck sauce by mixing the plum jam with the sugar, vinegar and chutney in a small serving bowl. Chop remaining green onions and place them into a separate bowl. Place whole duck onto a serving platter and garnish with orange slices and fresh parsley. Use plum sauce and onions for dipping.\"]'),('pho','[\"2 packs Vietnamese rice noodles\", \"4 ounces fresh beef slices\", \"Beef broth base\", \"2 pounds beef bones\", \"1 pound beef brisket\", \"1 onion\", \"5 liters water\", \"Broth seasonings\", \"4 thick slices ginger\", \"1 onion\", \"3 cinnamon sticks\", \"4 cardamom pods\", \"3 star anise\", \"4 sprigs cilantro stems\", \"1 teaspoon salt\", \"1 teaspoon sugar\", \"翻 cup fish sauce\", \"Garnishes\", \"4 ounces bean sprouts\", \"翻 onion\", \"A few red and green chilies\", \"A few chopped scallions\", \"Several stalks of scallions\", \"A small handful of basil\", \"A pinch of black pepper\", \"1/4 lime\"]','[\"Clean the beef bones in a large pot, blanch in boiling water for 5 minutes to remove excess fat and impurities. Remove and rinse the bones.\", \"Clean the pot, add beef bones, cleaned brisket, peeled whole onion, and 5 liters of water.\", \"Bring to a boil on high heat, then reduce to medium heat and simmer for 2 hours. During this time, prepare the broth seasonings.\", \"Cut ginger into thick slices about the size of a finger, halve the onion, wash cilantro stems, and set aside cinnamon sticks, cardamom pods, and star anise.\", \"Heat a dry pan and add the ginger, onion, cilantro stems, cinnamon, cardamom, and star anise. Toast over medium-high heat until fragrant.\", \"Once toasted, scrape off the burnt parts of the ginger and onion to avoid clouding the broth. Add the toasted seasonings to the beef broth and simmer to infuse the flavors.\", \"After 1 hour of simmering, remove the brisket and slice it.\", \"After 2 hours of simmering, add salt, sugar, and fish sauce to taste.\", \"Meanwhile, prepare the garnishes: blanch the bean sprouts in boiling water for 10 seconds, drain and set aside.\", \"Cut half an onion into thin strips and soak in ice water to remove the pungency.\", \"Deseed and dice the red and green chilies (keep the seeds for extra spice if desired), chop the scallions, split the white parts to enhance flavor, and wash the basil leaves.\", \"Cut the lime into 4 wedges. Optionally, prepare seafood sauce and sriracha.\", \"Cook the Vietnamese rice noodles according to the package instructions: soak in cold water for 5-10 minutes, then cook in boiling water for 6-8 minutes, drain and set aside.\", \"Thinly slice the fresh beef (ask your butcher to slice it thinly). If concerned, you can blanch it in boiling water briefly before use.\", \"For the soup, you can also use the simmered beef brisket or beef meatballs as an alternative to fresh beef slices.\", \"To serve, place noodles, fresh beef slices, scallions, white scallions, black pepper, bean sprouts, onion, chilies, etc., in a bowl.\", \"Bring the broth to a boil, pour it over the noodles to cook the beef slices, then add lime juice and basil, stir, and serve.\"]'),('pizza','[\"4 c. self-rising flour\", \"1/4 c. sugar\", \"2 c. warm milk\", \"1/3 c. oil\"]','[\"Dissolve yeast in milk; add oil, flour and sugar.\", \"Knead 3 to 4 minutes.\", \"Divide and then spread on a greased pizza pan or cookie sheet.\", \"Let rise for 15 to 30 minutes.\", \"Bake 15 minutes. Take out and add sauce, meat, etc. and then cheese.\", \"Cook until cheese melts.\", \"For sauce use 1 jar Always Save spaghetti sauce. Add your own spices.\", \"Use Velveeta, Cheddar or Mozzarella cheeses.\"]'),('pork_chop','[\"1 medium onion\", \"1 large pepper\", \"1 can stewed tomatoes, chopped\", \"2 tsp. sugar\", \"salt and pepper to taste\", \"1/2 c. V-8 tomato juice\", \"4 to 5 pork chops\"]','[\"Clean the beef bones in a large pot, blanch in boiling water for 5 minutes to remove excess fat and impurities. Remove and rinse the bones.\", \"Clean the pot, add beef bones, cleaned brisket, peeled whole onion, and 5 liters of water.\", \"Bring to a boil on high heat, then reduce to medium heat and simmer for 2 hours. During this time, prepare the broth seasonings.\", \"Cut ginger into thick slices about the size of a finger, halve the onion, wash cilantro stems, and set aside cinnamon sticks, cardamom pods, and star anise.\", \"Heat a dry pan and add the ginger, onion, cilantro stems, cinnamon, cardamom, and star anise. Toast over medium-high heat until fragrant.\", \"Once toasted, scrape off the burnt parts of the ginger and onion to avoid clouding the broth. Add the toasted seasonings to the beef broth and simmer to infuse the flavors.\", \"After 1 hour of simmering, remove the brisket and slice it.\", \"After 2 hours of simmering, add salt, sugar, and fish sauce to taste.\", \"Meanwhile, prepare the garnishes: blanch the bean sprouts in boiling water for 10 seconds, drain and set aside.\", \"Cut half an onion into thin strips and soak in ice water to remove the pungency.\", \"Deseed and dice the red and green chilies (keep the seeds for extra spice if desired), chop the scallions, split the white parts to enhance flavor, and wash the basil leaves.\", \"Cut the lime into 4 wedges. Optionally, prepare seafood sauce and sriracha.\", \"Cook the Vietnamese rice noodles according to the package instructions: soak in cold water for 5-10 minutes, then cook in boiling water for 6-8 minutes, drain and set aside.\", \"Thinly slice the fresh beef (ask your butcher to slice it thinly). If concerned, you can blanch it in boiling water briefly before use.\", \"For the soup, you can also use the simmered beef brisket or beef meatballs as an alternative to fresh beef slices.\", \"To serve, place noodles, fresh beef slices, scallions, white scallions, black pepper, bean sprouts, onion, chilies, etc., in a bowl.\", \"Bring the broth to a boil, pour it over the noodles to cook the beef slices, then add lime juice and basil, stir, and serve.\"]'),('poutine','[\"3 tablespoons extra-virgin olive oil\", \"1 teaspoon salt\", \"1 teaspoon freshly ground black pepper\", \"1/2 teaspoon garlic powder\", \"1 teaspoon dried parsley\", \"5 red potatoes, scrubbed and cut into wedges\", \"2 (.75 ounce) packets brown gravy mix\", \"2 cups low-sodium chicken broth\", \"2 cups cheese curds\"]','[\"Preheat oven to 350 degrees F (175 degrees C).\", \"Combine extra-virgin olive oil, salt, black pepper, garlic powder, and parsley in a large zip lock bag; add cut red potatoes and shake until potatoes are covered.\", \"Line a cookie sheet with foil; lightly cover with oil. Arrange potatoes on cookie sheet. Bake potatoes, flipping every 20 minutes, until golden brown, about 45 minutes to 1 hour. Transfer fries to a large bowl.\", \"Whisk brown gravy mix with chicken broth in a saucepan, place over medium heat, and bring to a boil, whisking often. Reduce heat to low; simmer for 1 minute, continuing to whisk. Let stand off the heat for 1 minute for gravy to thicken.\", \"Layer cheese curds over fries and top with prepared gravy.\"]'),('prime_rib','[\"1 large prime rib roast\", \"12 cloves garlic\", \"3 Tbsp. kosher salt\", \"3 Tbsp. pepper\", \"1 1/2 Tbsp. paprika\"]','[\"Cover meat with all ingredients.\", \"Cover with rock salt all over top.\", \"Bake, uncovered, at 200° for 3 to 4 hours or if a large roast, bake 7 to 8 hours.\"]'),('pulled_pork_sandwich','[\"1 1/2 cups barbeque sauce, or more as desired\", \"1/2 cup chopped white onion\", \"1/4 cup ketchup\", \"1/4 cup brown sugar\", \"1 teaspoon salt\", \"1 teaspoon ground black pepper\", \"1/2 teaspoon chili powder\", \"1 pound boneless pork loin, quartered\", \"4 onion rolls, halved\"]','[\"Stir barbeque sauce, onion, ketchup, brown sugar, salt, black pepper, and chili powder in slow cooker; add pork loin and coat with sauce. Cover and cook on High until pork is very tender, about 4 1/2 hours. Shred pork with 2 forks. Keep warm on Low until ready to serve.\", \"Serve on onion rolls.\"]'),('ramen','[\"1 pkg. Ramen Oriental noodles\", \"4 c. chopped cabbage\", \"3 Tbsp. sugar\", \"3 Tbsp. vinegar\", \"2 Tbsp. olive oil\", \"dry soup base packet\"]','[\"Cook noodles according to package and drain.\", \"Mix sugar, vinegar, dry soup base and olive oil.\", \"Add to cabbage and drained noodles.\", \"Toss gently and chill.\", \"May add nuts, chicken or shrimp.\"]'),('ravioli','[\"2 lb. can Ricotta cheese\", \"8 eggs (large)\", \"handful of Romano cheese, grated\", \"salt\", \"pepper\", \"3 c. flour\", \"8 oz. water\"]','[\"Mix together in a bowl the Ricotta cheese, 5 eggs, Romano cheese and salt and pepper to taste.\", \"Beat with electric mixer. Set aside.\"]'),('red_velvet_cake','[\"2 c. Wesson oil\", \"2 1/2 c. plain flour\", \"1 1/2 c. sugar\", \"1 c. buttermilk\", \"2 eggs\", \"2 tsp. cocoa\", \"2 tsp. soda\", \"1 tsp. baking powder\", \"1 tsp. vinegar\", \"1 oz. red food coloring\", \"1 tsp. vanilla\"]','[\"Grease and flour pans.\", \"(Makes three (9-inch) layers.) Mix all ingredients together and bake at 350° for 30 minutes.\"]'),('risotto','[\"3 c. low salt chicken broth\", \"1 medium onion, chopped\", \"6 Tbsp. extra virgin flavorful olive oil\", \"1 1/3 c. raw Italian Arborio rice\", \"1/3 c. grated Parmesan cheese\", \"1/4 tsp. black pepper\"]','[\"In a medium pan, heat chicken broth to a simmer over medium heat.\", \"While broth is heating, saute onion in oil for 3 or 5 minutes until soft.\", \"Add rice and stir to coat with oil.\", \"Add 1/2 cup broth and stir with a wooden spoon until the broth has been absorbed.\", \"Continue this pattern with rest of broth, adding it 1/2 cup at a time and stirring until it is absorbed by the rice.\", \"When you have used all the broth, test the rice to see if it is still too chewy.\", \"If so, add more hot broth or hot water until it reaches the desired consistency.\", \"Remove from heat and stir in cheese and black pepper.\"]'),('samosa','[\"8 oz. potatoes, cut in even size pieces\", \"3/4 c. frozen green peas\", \"2 Tbsp. corn oil\", \"1 onion, finely chopped\", \"1/2 tsp. cumin seed\", \"1 (1/2-inch) piece ginger root, peeled and grated\", \"1/2 tsp. turmeric\", \"1/2 tsp. Garam Masala\", \"1/2 tsp. salt\", \"2 tsp. lemon juice\", \"1 c. all-purpose flour\", \"2 Tbsp. butter\", \"2 Tbsp. warm milk\", \"vegetable oil for deep frying\", \"lime twists, if desired\", \"fresh celery leaves, if desired\", \"Mango Chutney\"]','[\"In a saucepan, boil potatoes in salted water 15 to 20 minutes or until tender.\", \"Drain well, return to saucepan and shake over low heat a few moments or until dry.\", \"Mash well.\", \"Cook peas in boiling salted water 4 minutes.\", \"Drain well.\"]'),('sashimi','[\"1/2 to 1 lb. fresh ahi\", \"2 to 3 Tbsp. garlic, minced\", \"4 Tbsp. capers\", \"1/4 c. virgin olive oil\", \"1/4 c. balsamic vinegar or other seasoned vinegar\", \"grated fresh Parmesan cheese (may use fresh Romano cheese)\"]','[\"Thinly slice ahi and lay on platter.\", \"Cover with plastic wrap. Use wooden meat hammer to pound thin.\", \"Remove plastic wrap.\", \"Spread minced (or crushed) garlic over ahi.\", \"Grate fresh Parmesan and sprinkle capers.\", \"Chill until ready to serve.\", \"Mix olive oil and seasoned vinegar in a small covered jar.\", \"Shake well.\", \"Just prior to serving, pour vinegar and oil mixture evenly over the dish and enjoy.\"]'),('scallops','[\"6 oz. onion cheese\", \"1/4 c. dry white wine\", \"1 medium onion, chopped\", \"1 c. real mayonnaise\", \"1 lb. bay scallops\", \"1/2 lb. mushrooms, sliced\"]','[\"Stir together the cheese, mayonnaise and wine; reserve.\", \"In a 10-inch skillet over medium-high heat, melt 2 tablespoons butter; add the scallops and cook, stirring, just until they are opaque, a minute or so.\", \"With a slotted spoon, remove scallops to paper toweling to drain.\", \"Add the remaining 2 tablespoons butter to the skillet with the onion; cook gently until slightly golden and add mushrooms.\", \"Cook rapidly, stirring, so they do not release their liquid, a few minutes.\", \"Turn off heat and stir in the reserved cheese mixture and scallops.\", \"Bake in casserole until warmed through.\", \"Serve over noodles.\"]'),('seaweed_salad','[\"1 pkg. lemon jello\", \"1 pkg. lime jello\", \"1 1/2 c. boiling water\", \"1 (No. 2) can crushed pineapple\", \"1 c. evaporated milk\", \"pinch of salt\", \"1 lb. cottage cheese\", \"1 c. mayonnaise\", \"1 Tbsp. horseradish\", \"1 c. nuts\"]','[\"Make day before.\", \"Combine jello and water, then add other ingredients, leaving cottage cheese and nuts last.\", \"Keep in refrigerator until ready to use.\", \"Serve on lettuce leaf, if desired.\"]'),('shrimp_and_grits','[\"1 lb. fresh shrimp, peeled\", \"6 slices bacon\", \"peanut oil\", \"2 c. sliced mushrooms\", \"1 c. scallions or green onions\", \"1 large clove garlic, minced\", \"4 tsp. lemon juice\", \"Tabasco sauce\", \"chopped parsley\", \"salt and pepper to taste\", \"Cheese Grits (see index)\"]','[\"Wash shrimp and pat dry.\", \"Dice bacon and cook until just crisp in a large skillet. Drain bacon and reserve. Add enough oil to bacon fat to make a thin layer.\", \"When hot, add shrimp.\", \"Stir about and add scallions and garlic.\", \"Season to taste with lemon, hot sauce, parsley, salt and pepper. Divide grits. Spoon shrimp over grits and top with bacon.\", \"Serves 4.\"]'),('spaghetti_bolognese','[\"1 lb. ground beef\", \"1 onion\", \"1/2 lb. mushrooms\", \"1 oz. butter\", \"garlic to taste\", \"2 Tbsp. Worcestershire sauce\", \"1 c. ketchup\", \"1 tsp. paprika\", \"1 c. Naturally Fresh sweet and sour sauce\", \"1 packet spaghetti\"]','[\"Fry meat until brown.\", \"In separate pan, fry mushrooms, garlic and onions in the butter.\", \"Drain off fat from both pans and join together.\", \"Cook spaghetti as directed on package.\", \"Add all other ingredients, stirring until blended.\", \"Cook over medium heat while spaghetti is cooking.\"]'),('spaghetti_carbonara','[\"3 gloves garlic\", \"1/2 lb. bacon, chopped\", \"1/4 c. white wine\", \"salt and pepper\", \"grated cheese\", \"1 medium onion, chopped\", \"1 pkg. frozen peas\", \"1/4 c. chicken broth\", \"1 egg, beaten\", \"1 lb. spaghetti\"]','[\"Saute onion, garlic and bacon together.\", \"Add wine and broth; cook 10 minutes.\", \"Add defrosted peas; continue cooking over medium heat for 5 more minutes.\", \"Cook spaghetti according to package directions.\", \"Add mixture to spaghetti.\", \"Add egg and cheese; mix well and serve.\"]'),('spring_rolls','[\"1 c. ground pork\", \"1/2 c. cooked shrimp, chopped\", \"1/2 c. crab meat, boiled\", \"1 c. bean sprouts\", \"1 Tbsp. sugar\", \"2 Tbsp. chopped green onion\", \"2 Tbsp. chopped celery leaves\", \"2 tsp. salt\", \"1/2 c. jelly noodles (a kind of transparent vermicelli made of mung bean)\", \"1/2 Tbsp. chopped garlic\", \"6 dried black mushrooms, chopped\", \"1 Tbsp. nampla (fish sauce)\", \"1 Tbsp. soy sauce\", \"4 eggs, slightly beaten, fried and chopped\", \"1 egg yolk\", \"2 c. vegetable oil\", \"1 tsp. pepper\"]','[\"Heat vegetable oil in frying pan.\", \"Add chopped garlic and fry for 2 minutes.\", \"Put in ground pork, shrimp, crab meat, bean sprouts, eggs, green onion, celery, black mushrooms and jelly noodles.\", \"Fry for 5 minutes.\", \"Add soy sauce, nampla, salt and pepper\"]'),('steak','[\"1 whole deer tenderloin steak\", \"bacon\", \"wine\", \"A.1. steak sauce\", \"onion\", \"pepper\", \"butter\", \"season salt\"]','[\"Take whole deer tenderloin steak, put 5 or 6 slices of bacon in pan, a little cooking wine (red) and a little A.1.\", \"steak sauce.\", \"Add sliced onion and pepper.\", \"Fry all in butter for 5 to 7 minutes on high.\", \"Add a little Morton Nature Season.\"]'),('strawberry_shortcake','[\"1 1/2 c. sugar\", \"1/2 c. Crisco, melted\", \"2 eggs\", \"2 tsp. baking powder\", \"1 1/2 c. flour\", \"1 c. milk\", \"2 tsp. vanilla\"]','[\"Add, in the order listed, and mix well.\", \"Pour into oblong baking pan or dish.\", \"Bake at 375° for 40 minutes.\", \"Cool and add fresh strawberries and milk, if so desired.\"]'),('sushi','[\"1 c. water\", \"3 Tbsp. white vinegar\", \"2 Tbsp. sugar\", \"3/4 c. short-grain rice\", \"6 Nori seaweed squares\", \"soy sauce\", \"wasabi\", \"filling of choice (see following)\"]','[\"Combine rice, water, sugar and vinegar in a saucepan.\", \"Bring to a boil.\", \"Turn fire down to low.\", \"Cover and cook until rice is done.\", \"Allow to cool to room temperature.\", \"Toast Nori lightly by waving briefly over an open flame.\", \"Place on a kitchen towel or a sushi mat.\", \"Top with a thin layer of rice, leaving 1/2-inch at far end of Nori uncovered.\", \"Along the proximal end of the square, line up your filling of choice.\", \"Roll in jelly roll fashion, using the mat or towel as an aid.\", \"Remember that 1/2-inch of the tail end of the Nori you left uncovered?\", \"Dampen it with a wet finger and use it to seal your sushi roll. You should end up with a sausage-like black tube, the filling in the middle.\"]'),('tacos','[\"1 pkg. shaped taco shells or 1 pkg. soft tortillas\", \"1 lb. ground beef or turkey\", \"grated Cheddar cheese\", \"chopped olives\", \"chopped tomatoes\", \"shredded cheese\", \"sour cream\", \"hot sauce\"]','[\"Brown chopped meat, stirring often.\", \"Add salt and pepper to taste.\", \"Drain off fat.\", \"Put ground meat in a bowl.\", \"Everyone puts their favorite things on their own tacos.\", \"Eat and enjoy.\"]'),('takoyaki','[\"10.5 ounces Cake Flour\", \"3 Eggs - beaten\", \"4.25 cups Ice Cold Water\", \"1/2 teaspoon Salt\", \"1 teaspoon Hondashi Granules\", \"2 teaspoons Ponzu or Yuzupon Sauce\", \"1/2 pound Boiled Octopus Legs (cut into 1/2\\\" pieces)\", \"4 Green Onions Minced\", \"1 bunch Pickled Ginger Minced\", \"1 cup Rice Crispy Cearal\", \"Oil\", \"Aonori (Dried Seaweed Powder)\", \"Takoyaki Sauce\", \"Mayonnaise\", \"Bonito Flake\"]','[\"Blend the ice water and dashi stock granules until dissolved. Add the sauce and eggs. Add the flour, and mix together gently. Do not over mix, the batter will be slightly lumpy.\", \"Wad up a paper towel into a fat cigar shape and soak one end with oil. Oil each hole in the pan as well as the surface. Pour batter into each hole 2/3rds full. (pour in a clockwise direction starting at 12:00 so you remember where you started) Add 1 piece of octopus to each hole and sprinkle in a little bit each of the following: green onion, ginger and cereal. When finished fill each hole to the top with batter.\", \"Use wooden chopsticks to sweep the edge of the first hole you poured. Once it starts to release (about 3 minutes total) sweep the chopstick under to flip the takoyaki on its side 90 degrees. Let the uncooked batter on top fall into the bottom the flip the takoyaki the whole way. Continue cooking and spinning the balls until they are evenly golden brown on all sides. (an additional 4-5 minutes total from the 90 degree flip)\", \"Top with takoyaki sauce, mayonnaise, bonito flake and aonori. Enjoy!\"]'),('tiramisu','[\"8 oz. bittersweet chocolate\", \"24 ladyfingers\", \"2 c. strong Espresso coffee, cooled\", \"6 eggs, separated\", \"6 heaping Tbsp. granulated sugar\", \"1 lb. Mascarpone\"]','[\"Chop the chocolate coarsely or cut into small pieces.\", \"Put ladyfingers on a plate and lightly soak them with cold coffee. Arrange half of the ladyfingers in 1 layer on a rectangular or oval serving dish with sides at least 2 inches high.\"]'),('tuna_tartare','[\"1 pound sushi grade tuna, finely diced\", \"3 tablespoons olive oil\", \"1/4 teaspoon wasabi powder\", \"1 tablespoon sesame seeds\", \"1/8 teaspoon cracked black pepper\", \"sliced French bread\"]','[\"In a bowl, stir together olive oil, wasabi powder, sesame seeds, and cracked black pepper. Toss tuna into mixture until evenly coated. Adjust seasoning as desired with additional wasabi powder or black pepper. Serve on sliced French bread.\"]'),('waffles','[\"2 c. flour\", \"2 c. milk\", \"3 tsp. baking powder\", \"1/2 tsp. salt\", \"4 Tbsp. melted butter\", \"2 eggs, beat separately\"]','[\"Sift flour, salt and baking powder into bowl.\", \"Beat yolks well and add milk.\", \"Beat, adding this to the flour mixture, slowly beating until smooth.\", \"Add melted butter and fold in stiffly beaten egg whites.\", \"Makes four big ones.\"]');
